// === Tab: mySketch ===
let raindrops= []
let speed = 8
let woebots= [];

function setup() {
  createCanvas(windowWidth, windowHeight);

  for(i=0; i<width; i+=100){
    woebots.push(new woebot(i, windowHeight*.8, random(25, 60)))
  }
  raindrops.push(new Raindrop())
 // angleMode(DEGREES)
}

function draw() {
 background(240);

  stroke(50, 100, 255, 150)
  strokeWeight(.5)
  fill(50, 100, 255, 100)
  //ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 175, 200)

  raindrops.push(new Raindrop())
  for(let i=0; i<raindrops.length; i++){
    raindrops[i].fall();
    raindrops[i].display();  
  }

  for (let i=0; i<woebots.length; i++) {
    woebots[i].display()
    if(woebots[i].active==1){
    woebots[i].walk()
    woebots[i].look()
    woebots[i].travel()
    }

    }


  //sidewalk
  for(let i=-100; i<width; i+=50){
   push()
   translate(i, height*0.85)
   shearX(60)
   rect(0, 0, 40)
   pop()
 }

//mountains

for(i=0; i<180; i+=1){
beginShape();
  noFill()
  stroke(230, 255, 220, 255-(i*1.5))
  curveVertex(0, (height/2)-50+i);
  curveVertex(0, height/2+i/2);
  curveVertex(width*.33, height*.25+i);
  curveVertex(width*.75, height*.5+i/2)
  curveVertex(width, height*.33+i)
  curveVertex(width+20, height/33+20+i)
endShape();
}
//clouds
  ellipseMode(CENTER)

 for(let i=-50; i<width+50; i+=60){
   fill(200)
   ellipse(i, 20, 75, 50)
   fill(180)
   ellipse(i, 10, 75, 50)
 }

 //print(raindrops.length)

}

class Raindrop{
  constructor(){
  this.x = random(width)
  this.y = 0
  this.diameter= random (1, 5)
}


fall(){
  this.y+=speed
  if(this.y>=height){

  let index = raindrops.indexOf(this);
      raindrops.splice(index, 1);
    }   

  }
display() {
  ellipse(this.x, this.y, this.diameter, this.diameter)
}

}


 class woebot{
    constructor(x, y, size){
      this.x=x
      this.y=y
      this.size=size
      this.arml=0
      this.armr=0
      this.legl=0
      this.legr=0
      this.mover=1
      this.looky=0
      this.active=1
    }

  display(){
  ellipseMode(CENTER)
  fill(0, 60)
    noStroke()
  //head
  ellipse(this.x, this.y-this.size, this.size)
  //mouth
  ellipse(this.x, this.y-this.size*.66, this.size/4, this.size/10)

  //eyes
  ellipse(this.x-this.size/5, this.y-this.size, this.size/3)
  ellipse(this.x+this.size/5, this.y-this.size, this.size/3)
  if(this.looky==0){
    ellipseMode(CENTER)
  }else{
    ellipseMode(CORNER)
  }
  push()
  translate(this.x+this.size/5, this.y-this.size)
  let a=atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.y-this.size, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.x );
  rotate(a);
  ellipse(0, 0, this.size/6)
  pop()
  push()
  translate(this.x-this.size/5, this.y-this.size)
  rotate(a);
  ellipse(0, 0, this.size/6)
  pop()

  //body
  rectMode(CENTER)
  rect(this.x, this.y, this.size*.75, this.size, 20)
  rect(this.x, this.y, this.size*.5, this.size*.5, 10)
  //arms
  rectMode(CORNER)
  push()
  translate(this.x-this.size*.6, this.y-this.size*.4);
  rotate(this.arml);
  rect(0, 0, this.size/4, this.size, 20);
  pop();
  push();
  translate(this.x+this.size*.33, this.y-this.size*.4);
  rotate(this.armr);
  rect(0, 0, this.size/4, this.size, 20)
  pop()
  //legs
  push();
  translate(this.x-this.size/4, this.y+this.size/2)
  rotate(this.legl)
  rect(0, 0, this.size/4, this.size, 20);
  pop()
  push()
  translate(this.x+this.size*.05, this.y+this.size/2);
  rotate(this.legr)
  rect(0, 0, this.size/4, this.size, 20);
  pop();
  }

  walk(){
      this.mover+=.1;
      this.arml= sin(this.mover)/2
      this.armr= -sin(this.mover)/2
      this.legl= -sin(this.mover)/2
      this.legr= sin(this.mover)/2

    }
  look(){
    this.looky=1
  }

  travel(){
    this.x+=1
    if(this.x>width+50){
      this.x=0-50
    }
  }
   whoa(){
    if((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))<this.x+this.size/2 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))>this.x-this.size/2 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))<this.y+this.size && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))>this.y-this.size){
      if(this.active==1){
        this.active=0
        this.looky=0
      } else
      {
        this.active=1
      }
    }
  }
 }

function mouseClicked(){
  for(i=0; i<30; i++){
  raindrops.push(new Raindrop())
  }
  for (let woebot of woebots) {
    woebot.whoa()
  }
}

